261	    /**
262	     * Return the Pet with the given name, or null if none found for this Owner.
263	     *
264	     * @param name to test
265	     * @return true if pet name is already in use
266	     */
267	    public Pet getPet(String name, boolean ignoreNew) {
268	        name = name.toLowerCase();
269	        for (Pet pet : getPetsInternal()) {
270	            if (!ignoreNew || !pet.isNew()) {
271	                String compName = pet.getName();
272	                compName = compName.toLowerCase();
273	                if (compName.equals(name)) {
274	                    return pet;
275	                }
276	            }
277	        }
278	        return null;
279	    }
